            "date": {"type": "string", "description": "YYYY-MM-DD"},
        },
        "required": ["origin", "destination", "date"],
    },
    fn=_rail,
)

weather_tool = Tool(
    name="query_weather",
    description="One-day forecast for a city. Keys: hangzhou, shanghai, changsha.",
    parameters={
        "type": "object",
        "properties": {"city": {"type": "string"}},
        "required": ["city"],
    },
    fn=_weather,
)

court_tool = Tool(
    name="find_basketball_courts",
    description="Nearby basketball venues, optionally restricted to indoor courts.",
    parameters={
        "type": "object",
        "properties": {
            "city": {"type": "string"},
            "indoor_only": {"type": "boolean", "default": True},
        },
        "required": ["city", "indoor_only"],
    },
    fn=_courts,
)

note_tool = Tool(
    name="save_memory_note",
    description="Persist a note to long-term memory. This has a side effect.",
    parameters={
        "type": "object",
        "properties": {"text": {"type": "string"}},
        "required": ["text"],
    },
    fn=_save_note,
    requires_approval=True,
)

